param([Parameter(Mandatory)][ValidateSet('BASELINE','REMEDIATION')][string]$Condition,[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN',[int]$DurationSeconds=300)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$result=Join-Path $root 'backend\experiments\results\experiment-1-26\probes-recovery3';$dir=Join-Path $result $Condition
if($ExecutionMode-eq'PLAN'){Write-Output "EXP126_$Condition`_PROBE_PLAN_READY";exit 0};if(Test-Path $dir){throw "PROBE_COLLISION: $dir"};New-Item -ItemType Directory -Force $dir|Out-Null
$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml');$compose=@();foreach($f in $files){$compose+=@('-f',(Join-Path $root $f))};$project='doeng-exp126-core';$collector=$null;$old=@{}
try{
 $policy=if($Condition -eq 'BASELINE'){@{leasingStrategy='FIFO';maxIdleTimeMs=0;evictionIntervalMs=0}}else{@{leasingStrategy='LIFO';maxIdleTimeMs=3000;evictionIntervalMs=1000}}
 foreach($e in @{'DOENG_EXTERNAL_LEASING_STRATEGY'=$policy.leasingStrategy;'DOENG_EXTERNAL_MAX_IDLE_TIME_MS'=$policy.maxIdleTimeMs;'DOENG_EXTERNAL_EVICTION_INTERVAL_MS'=$policy.evictionIntervalMs}.GetEnumerator()){$old[$e.Key]=[Environment]::GetEnvironmentVariable($e.Key,'Process');[Environment]::SetEnvironmentVariable($e.Key,[string]$e.Value,'Process')}
 docker compose -p $project @compose up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'FRESH_RECREATE_FAILED'}
 $health=$false;for($i=0;$i-lt30;$i++){try{if((Invoke-WebRequest -UseBasicParsing http://127.0.0.1:9001/actuator/health -TimeoutSec 2).StatusCode-eq200){$health=$true;break}}catch{};Start-Sleep -Seconds 1};if(-not$health){throw 'HEALTH_FAILED'}
 $out=Join-Path $dir 'pool-metrics.jsonl';$sum=Join-Path $dir 'pool-metrics.jsonl.summary.json';$signal=Join-Path $dir 'STOP-COLLECTOR';$collector=Start-Process powershell.exe -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-experiment-1-26-pool-until-stop.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',$out,'-SummaryPath',$sum,'-StopSignalPath',$signal,'-IntervalMilliseconds','1000','-RequestTimeoutSeconds','5','-MaxDurationSeconds',$DurationSeconds)
 $ready=$false;for($i=0;$i-lt100;$i++){if(Test-Path $out){$valid=Get-Content $out|Where-Object{$_-match '"ok":true'};if($valid){$ready=$true;break}};Start-Sleep -Milliseconds 100};if(-not$ready){throw 'COLLECTOR_NOT_READY'}
 Start-Sleep -Seconds ([math]::Max(1,$DurationSeconds-5));New-Item -ItemType File -Force $signal|Out-Null;if(-not$collector.WaitForExit(15000)){throw 'COLLECTOR_STOP_TIMEOUT'};$s=Get-Content $sum -Raw|ConvertFrom-Json;if($s.failures-ne0 -or $s.stopSignalObserved-ne$true -or $collector.ExitCode-ne0 -or $s.maximumValidSampleGapMilliseconds-gt6000){throw 'COLLECTOR_RELIABILITY_FAILED'}
 [ordered]@{experiment='Experiment 1-26';condition=$Condition;status='PRODUCTION_PATH_PROBE_PASSED';durationSeconds=$DurationSeconds;policy=$policy;attempts=$s.attempts;samples=$s.samples;failures=$s.failures;maxConsecutiveFailures=$s.maxConsecutiveFailures;skippedPolls=$s.skippedPolls;maximumValidSampleGapMilliseconds=$s.maximumValidSampleGapMilliseconds;collectorStatus=$s.collectorStatus;stopSignalObserved=$s.stopSignalObserved;warmupInvoked=0;k6Invoked=0;coreInvoked=0;collector=$s}|ConvertTo-Json -Depth 12|Set-Content (Join-Path $dir 'probe-summary.json') -Encoding UTF8;Write-Output "EXP126_$Condition`_PRODUCTION_PATH_PROBE_PASS"
}finally{if($null-ne$collector -and -not$collector.HasExited){$collector.Kill()};docker compose -p $project @compose down --remove-orphans|Out-Null;foreach($e in $old.GetEnumerator()){[Environment]::SetEnvironmentVariable($e.Key,$e.Value,'Process')}}
